[
  {
    "id": "rule-1",
    "fields": {
      "text": "The latest signed demand controls. A replacement restarts the response clock at its actual complete-receipt instant; an amount-only amendment inherits the original complete-receipt clock, response duration, and root demand identity. An amount-only amendment may add a required packet enclosure or supply a previously missing enclosure without restarting that clock. Use the current verified receipt inventory for packet completeness."
    }
  },
  {
    "id": "rule-2",
    "fields": {
      "text": "A written extension applies only if accepted by the named authorized recipient, received before the unextended deadline, and scoped to the controlling root demand. Add its stated minutes to the original clock duration. Missing required enclosures make the packet incomplete."
    }
  },
  {
    "id": "rule-3",
    "fields": {
      "text": "remainingMinutes is floor((deadlineAt-readingClock)/60000). urgency is overdue below zero, immediate from zero through 120 inclusive, and active above 120. Preserve old follow-ups as superseded history; exactly one current operative follow-up remains."
    }
  }
]

[
  {
    "id": "rule-1",
    "fields": {
      "text": "Deduplicate posted transactions by transactionKey, keeping the latest signed revision. Signed reversal rows are negative indemnity adjustments to their linked transaction. Only the named target claimant and BI coverage enter this per-person calculation; expenses and recoveries do not erode this synthetic BI limit."
    }
  },
  {
    "id": "rule-2",
    "fields": {
      "text": "Use the latest signed effective estimate as the reserve, replacing its earlier estimate; never add estimate versions. incurredCents = netPaidCents + reserveCents. availableLimitCents = max(0,perPersonLimitCents-incurredCents). Missing claimant allocation remains unallocatedCents and prevents postingReady."
    }
  },
  {
    "id": "rule-3",
    "fields": {
      "text": "A prior approval binds its exact material revision and proposal amount. New allocations, reversals, or estimate corrections invalidate it; preserve it as historical and request fresh internal review. No payment is made in this episode."
    }
  }
]

