[
  {
    "id": "rule-1",
    "fields": {
      "text": "A material document or exposure revision makes an approval of the prior packet historical. The current proposal and open gates must be rebuilt from the current packet revision; recorded prior human judgments remain in history."
    }
  },
  {
    "id": "rule-2",
    "fields": {
      "text": "A human workflow pin stays authoritative until a supplied human unpin action. System inference and internal proposals never overwrite it. Resolved exposures alone establish resolution/ready_to_close only when every gate is closed; explicit carrier closure evidence alone establishes closed/complete."
    }
  },
  {
    "id": "rule-3",
    "fields": {
      "text": "With an open gate, projectedPhase is review and projectedCondition awaiting_gate. Without an open gate, unresolved exposures imply investigation/active; resolved exposures imply resolution/ready_to_close absent carrier closure. Proposed orientation is separate from the human pin."
    }
  }
]
